def compute(vars):
    costs_million = vars["v1"]
    principal_billion = vars["v2"]
    principal_million = principal_billion * 1000

    if principal_million == 0:
        return None

    ratio = costs_million / principal_million
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "costs_million": costs_million,
            "principal_billion": principal_billion,
            "principal_million": principal_million,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "percentage",
                "unit": "percentage"
            }
        }
    }
